#include <iostream>
#include <string>
#include <algorithm>

bool IsVowel(char c) {
    return c == 'A' || c == 'E' || c == 'O' || c == 'U' || c == 'Y' || c == 'I';
}

int main() {
    std::string str;
    std::getline(std::cin, str);
    str = ' ' + str + ' ';
    int jumpSize = 1, pos = 0, next;
    do {
        next = pos + 1;
        while (str[next] != ' ' && !IsVowel(str[next])) {
            next++;
        }
        jumpSize = std::max(jumpSize, next - pos);
        pos = next;
    } while (str[pos] != ' ');
    std::cout << jumpSize << std::endl;
    return 0;
}

